var n=`0310-kebapche`;var t=`world-0310`;var o=`BG`;var r=`eastern-europe`;var l=4;var a=51;var u={en:`Kebapche`,ua:`Кебапче`};var s={en:`A traditional Bulgaria dish made with ground pork, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Болгарія. Основні інгредієнти: свинячий фарш, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`ground-pork`,630,`g`],[`yellow-onion`,120,`g`],[`ground-cumin`,5,`g`],[`ground-black-pepper`,null,`to_taste`],[`table-salt`,null,`to_taste`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 30 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 30 хвилин.`,t:[`rapid-chilling`],m:30,i:[]},{en:`Grill over medium-high heat for about 12 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 12 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:12,i:[[`sunflower-oil`,25,`ml`]]}];var g={slug:n,id:t,country:`BG`,region:r,servings:4,minutes:51,title:u,text:s,steps:d};export{o as country,g as default,t as id,a as minutes,r as region,l as servings,n as slug,d as steps,s as text,u as title};